// ===== CONTENT STRATEGY SELECTOR =====
// Picks the best content angle based on knowledge base

const input = $input.first().json;
const state = input.state || {};
const chatId = input.chatId;

// Get knowledge base from static data
const staticData = $getWorkflowStaticData('global');
const kb = staticData.knowledgeBase || {};

// Select best hook from knowledge base
const hooks = kb.topHooks || [
  'Stop scrolling if you...',
  'The truth about...',
  'Nobody talks about this...',
  'I wish I knew this sooner...',
  'The #1 mistake people make...',
  'This changed everything for me...',
  'You\'re doing it wrong if...',
  'The secret that experts won\'t tell you...'
];

// Select random hook for A/B testing
const selectedHook = hooks[Math.floor(Math.random() * hooks.length)];

// Select content angle
const contentIdeas = kb.contentIdeas || [
  'Common mistakes in the niche',
  'Beginner tips that actually work',
  'Top 5 things to know',
  'Myth vs Reality',
  'Step by step guide',
  'What I learned after X years',
  'The hard truth about...'
];
const selectedIdea = contentIdeas[Math.floor(Math.random() * contentIdeas.length)];

// Select hashtags
const hashtags = kb.topHashtags || [];
const selectedHashtags = hashtags.slice(0, 20).join(' #') || '#motivation #growth #success';

// Select CTA
const ctas = kb.topCTAs || [
  'Save this for later 🔖',
  'Share with someone who needs this 💫',
  'Double tap if you agree ❤️',
  'Follow for more tips 🚀',
  'Comment your thoughts below 💬'
];
const selectedCTA = ctas[Math.floor(Math.random() * ctas.length)];

// Select design style based on brand
const brandIdentity = state.brandIdentity || 'modern minimalist';
const designStyles = kb.designStyles || ['minimalist', 'bold', 'gradient', 'dark mode'];
const selectedDesign = designStyles[Math.floor(Math.random() * designStyles.length)];

// Select color palette
const colorPalettes = kb.colorPalettes || [
  { bg: '#1a1a2e', text: '#ffffff', accent: '#e94560' },
  { bg: '#0f0f0f', text: '#ffffff', accent: '#00ff88' },
  { bg: '#ffffff', text: '#1a1a1a', accent: '#ff6b35' }
];
const selectedColors = colorPalettes[Math.floor(Math.random() * colorPalettes.length)];

// Caption template
const captionTemplates = kb.captionTemplates || [];
const painPoints = kb.painPoints || [];

const caption = `${selectedHook}\n\n${selectedIdea}\n\n${painPoints.length > 0 ? '💡 ' + painPoints[0] : ''}\n\n${selectedCTA}\n\n.#${selectedHashtags}`;

// Carousel structure (6-10 slides)
const slideCount = 7;
const slides = [
  { type: 'cover', content: selectedHook, subtitle: selectedIdea },
  { type: 'problem', content: painPoints[0] || 'The biggest struggle in this niche' },
  { type: 'agitation', content: painPoints[1] || 'Why most people fail' },
  { type: 'solution', content: 'The game-changing approach' },
  { type: 'steps', content: 'Step by step breakdown' },
  { type: 'proof', content: 'Results and evidence' },
  { type: 'cta', content: selectedCTA }
];

return [{
  json: {
    chatId,
    hook: selectedHook,
    idea: selectedIdea,
    caption,
    hashtags: selectedHashtags,
    cta: selectedCTA,
    designStyle: selectedDesign,
    colors: selectedColors,
    brandIdentity,
    slides,
    slideCount,
    state,
    knowledgeBase: kb,
    abTestId: Date.now()
  }
}];

// ===== GENERATE CAROUSEL HTML =====
// Creates beautiful carousel slides using HTML/CSS/JS

const input = $input.first().json;
const { slides, colors, brandIdentity, hook, idea } = input;

// Generate HTML for each slide
function generateSlideHTML(slide, index, totalSlides) {
  const brandWatermark = '@YOUR_BRAND'; // Will be replaced with actual brand

  const baseStyles = `
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      width: 1080px;
      height: 1080px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
      overflow: hidden;
    }
    .slide {
      width: 1080px;
      height: 1080px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 80px;
      position: relative;
      background: ${colors.bg};
      color: ${colors.text};
    }
    .watermark {
      position: absolute;
      bottom: 20px;
      right: 30px;
      font-size: 16px;
      opacity: 0.4;
      letter-spacing: 1px;
    }
    .slide-number {
      position: absolute;
      bottom: 20px;
      left: 30px;
      font-size: 14px;
      opacity: 0.3;
    }
    .accent-line {
      width: 80px;
      height: 4px;
      background: ${colors.accent};
      margin: 20px 0;
      border-radius: 2px;
    }
  `;

  let slideContent = '';

  switch(slide.type) {
    case 'cover':
      slideContent = `
        <div class="slide" style="background: linear-gradient(135deg, ${colors.bg}, ${colors.accent}22);">
          <div style="text-align: center;">
            <div style="font-size: 28px; letter-spacing: 8px; text-transform: uppercase; opacity: 0.6; margin-bottom: 30px;">Swipe to learn →</div>
            <div class="accent-line" style="margin: 0 auto 30px;"></div>
            <h1 style="font-size: 64px; font-weight: 800; line-height: 1.2; margin-bottom: 20px;">${slide.content}</h1>
            <p style="font-size: 24px; opacity: 0.7; max-width: 700px;">${slide.subtitle}</p>
          </div>
          <div class="watermark">${brandWatermark}</div>
          <div class="slide-number">1/${totalSlides}</div>
        </div>
      `;
      break;

    case 'problem':
      slideContent = `
        <div class="slide">
          <div style="text-align: center;">
            <div style="font-size: 100px; margin-bottom: 30px;">😤</div>
            <h2 style="font-size: 48px; font-weight: 700; margin-bottom: 20px;">The Problem</h2>
            <div class="accent-line" style="margin: 0 auto 30px;"></div>
            <p style="font-size: 32px; line-height: 1.6; max-width: 800px;">${slide.content}</p>
          </div>
          <div class="watermark">${brandWatermark}</div>
          <div class="slide-number">2/${totalSlides}</div>
        </div>
      `;
      break;

    case 'agitation':
      slideContent = `
        <div class="slide" style="background: linear-gradient(135deg, ${colors.bg}, #ff000022);">
          <div style="text-align: center;">
            <div style="font-size: 100px; margin-bottom: 30px;">⚠️</div>
            <h2 style="font-size: 48px; font-weight: 700; margin-bottom: 20px;">Why This Matters</h2>
            <div class="accent-line" style="margin: 0 auto 30px; background: #ff4444;"></div>
            <p style="font-size: 32px; line-height: 1.6; max-width: 800px;">${slide.content}</p>
          </div>
          <div class="watermark">${brandWatermark}</div>
          <div class="slide-number">3/${totalSlides}</div>
        </div>
      `;
      break;

    case 'solution':
      slideContent = `
        <div class="slide" style="background: linear-gradient(135deg, ${colors.bg}, ${colors.accent}33);">
          <div style="text-align: center;">
            <div style="font-size: 100px; margin-bottom: 30px;">💡</div>
            <h2 style="font-size: 48px; font-weight: 700; margin-bottom: 20px;">The Solution</h2>
            <div class="accent-line" style="margin: 0 auto 30px;"></div>
            <p style="font-size: 32px; line-height: 1.6; max-width: 800px;">${slide.content}</p>
          </div>
          <div class="watermark">${brandWatermark}</div>
          <div class="slide-number">4/${totalSlides}</div>
        </div>
      `;
      break;

    case 'steps':
      const steps = [
        'Start with the basics',
        'Build consistent habits',
        'Track your progress',
        'Adjust and optimize'
      ];
      const stepsHTML = steps.map((s, i) => `
        <div style="display: flex; align-items: center; margin: 15px 0; text-align: left; width: 100%; max-width: 700px;">
          <div style="min-width: 60px; height: 60px; background: ${colors.accent}; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 28px; font-weight: 800; margin-right: 25px;">${i+1}</div>
          <p style="font-size: 28px; line-height: 1.4;">${s}</p>
        </div>
      `).join('');

      slideContent = `
        <div class="slide">
          <div style="text-align: center; width: 100%;">
            <h2 style="font-size: 48px; font-weight: 700; margin-bottom: 40px;">How To Do It</h2>
            <div class="accent-line" style="margin: 0 auto 40px;"></div>
            <div style="display: flex; flex-direction: column; align-items: center;">
              ${stepsHTML}
            </div>
          </div>
          <div class="watermark">${brandWatermark}</div>
          <div class="slide-number">5/${totalSlides}</div>
        </div>
      `;
      break;

    case 'proof':
      slideContent = `
        <div class="slide" style="background: linear-gradient(135deg, ${colors.bg}, ${colors.accent}22);">
          <div style="text-align: center;">
            <div style="font-size: 100px; margin-bottom: 30px;">🏆</div>
            <h2 style="font-size: 48px; font-weight: 700; margin-bottom: 20px;">Results Don't Lie</h2>
            <div class="accent-line" style="margin: 0 auto 30px;"></div>
            <p style="font-size: 32px; line-height: 1.6; max-width: 800px;">${slide.content}</p>
            <div style="margin-top: 40px; font-size: 80px; font-weight: 900; color: ${colors.accent};">+300%</div>
            <p style="font-size: 24px; opacity: 0.6;">improvement guaranteed</p>
          </div>
          <div class="watermark">${brandWatermark}</div>
          <div class="slide-number">6/${totalSlides}</div>
        </div>
      `;
      break;

    case 'cta':
      slideContent = `
        <div class="slide" style="background: linear-gradient(135deg, ${colors.accent}44, ${colors.bg});">
          <div style="text-align: center;">
            <div style="font-size: 100px; margin-bottom: 30px;">🔥</div>
            <h2 style="font-size: 52px; font-weight: 800; margin-bottom: 20px;">${slide.content}</h2>
            <div class="accent-line" style="margin: 0 auto 30px;"></div>
            <p style="font-size: 28px; opacity: 0.8;">Follow @YOUR_BRAND for more</p>
            <div style="margin-top: 40px; padding: 15px 40px; background: ${colors.accent}; border-radius: 50px; display: inline-block;">
              <p style="font-size: 24px; font-weight: 700;">FOLLOW →</p>
            </div>
          </div>
          <div class="watermark">${brandWatermark}</div>
          <div class="slide-number">7/${totalSlides}</div>
        </div>
      `;
      break;
  }

  return `<!DOCTYPE html>
<html>
<head>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&display=swap" rel="stylesheet">
  <style>${baseStyles}</style>
</head>
<body>${slideContent}</body>
</html>`;
}

// Generate all slides
const slidesHTML = slides.map((slide, index) => ({
  html: generateSlideHTML(slide, index, slides.length),
  type: slide.type,
  index: index
}));

return [{
  json: {
    ...input,
    slidesHTML
  }
}];

// ===== BROWSER SCREENSHOT =====
// Takes screenshots of each HTML slide using Playwright
// This node outputs URLs for the Playwright browser node

const input = $input.first().json;
const { slidesHTML, abTestId } = input;

// Generate local file paths for each slide
const screenshotPaths = slidesHTML.map((slide, index) => ({
  html: slide.html,
  outputPath: `/tmp/carousel_${abTestId}_slide_${index + 1}.png`,
  slideType: slide.type,
  slideIndex: index
}));

return [{
  json: {
    ...input,
    screenshotPaths
  }
}];

// ===== IMAGE UPLOAD TO IMGBB =====
// Uploads all carousel images to free image hosting

const input = $input.first().json;
const { screenshotPaths, abTestId, caption, hashtags, cta, chatId } = input;

// Prepare upload data for each image
const uploadTasks = screenshotPaths.map((path, index) => ({
  filePath: path.outputPath,
  slideType: path.slideType,
  slideIndex: index,
  fileName: `carousel_${abTestId}_${index + 1}.png`
}));

return [{
  json: {
    ...input,
    uploadTasks
  }
}];

// ===== UPLOAD TO TELEGRAPH (FREE) =====
// Uses Telegram's Telegraph for free image hosting

const input = $input.first().json;
const fs = require('fs');
const FormData = require('form-data');
const https = require('https');

const uploadResults = [];

for (const task of input.uploadTasks) {
  try {
    // Read file and convert to base64
    const fileBuffer = fs.readFileSync(task.filePath);
    const base64 = fileBuffer.toString('base64');

    // Upload to Telegraph
    const result = await new Promise((resolve, reject) => {
      const postData = JSON.stringify({
        file: `data:image/png;base64,${base64}`
      });

      const options = {
        hostname: 'telegra.ph',
        path: '/upload',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => resolve(JSON.parse(data)));
      });

      req.on('error', reject);
      req.write(postData);
      req.end();
    });

    if (result && result[0] && result[0].src) {
      uploadResults.push({
        url: `https://telegra.ph${result[0].src}`,
        slideType: task.slideType,
        slideIndex: task.slideIndex
      });
    }
  } catch (error) {
    uploadResults.push({
      url: null,
      error: error.message,
      slideType: task.slideType,
      slideIndex: task.slideIndex
    });
  }
}

return [{
  json: {
    ...input,
    imageUrls: uploadResults.filter(r => r.url).map(r => r.url),
    uploadResults
  }
}];

// ===== POST TO INSTAGRAM =====
// Uses Instagram's API to post the carousel

const input = $input.first().json;
const { imageUrls, caption, igCredentials, chatId } = input;

// Instagram Graph API carousel posting
// Note: This requires Instagram Business account connected via Facebook

const postResult = {
  status: 'ready_to_post',
  imageUrls: imageUrls,
  caption: caption,
  hashtags: input.hashtags,
  cta: input.cta,
  scheduledTime: null,
  postType: 'carousel'
};

// Store post data for tracking
const staticData = $getWorkflowStaticData('global');
if (!staticData.posts) staticData.posts = [];

const postData = {
  id: `post_${Date.now()}`,
  createdAt: new Date().toISOString(),
  hook: input.hook,
  idea: input.idea,
  caption: caption,
  hashtags: input.hashtags,
  imageUrls: imageUrls,
  slideCount: imageUrls.length,
  abTestId: input.abTestId,
  designStyle: input.designStyle,
  colors: input.colors,
  views: 0,
  likes: 0,
  comments: 0,
  saves: 0,
  shares: 0,
  reach: 0,
  impressions: 0,
  engagementRate: 0,
  status: 'posted',
  performanceNotes: []
};

staticData.posts.push(postData);

return [{
  json: {
    ...postResult,
    postData,
    chatId
  }
}];

// ===== SAVE POST TO NOCODB =====
// Stores post data for analytics tracking

const input = $input.first().json;

return [{
  json: {
    table: 'posts',
    data: {
      post_id: input.postData.id,
      created_at: input.postData.createdAt,
      hook: input.postData.hook,
      idea: input.postData.idea,
      caption: input.postData.caption,
      hashtags: input.postData.hashtags,
      image_urls: JSON.stringify(input.postData.imageUrls),
      slide_count: input.postData.slideCount,
      ab_test_id: input.postData.abTestId,
      design_style: input.postData.designStyle,
      status: 'posted',
      views: 0,
      likes: 0,
      comments: 0,
      saves: 0,
      shares: 0
    },
    chatId: input.chatId
  }
}];

